/**
 * Directory-mount overlays: a same-named file replaces, disable() removes.
 * Slot loaders do the walk; this file only applies replace/disable.
 */
import { join } from "node:path";
import { getDefinitionKind } from "../brand.js";
import { loadChannels } from "./channels.js";
import { displayPath, pushModuleLoadDiagnostic } from "./context.js";
import { findModuleFile, isDirectory, isFile, isModuleFile, moduleStem, sortedEntries, } from "./fs.js";
import { loadHooks } from "./hooks.js";
import { loadInstructions } from "./instructions.js";
import { importDefault } from "./modules.js";
import { loadSchedules } from "./schedules.js";
import { loadSkills } from "./skills.js";
import { loadSubagents } from "./subagent.js";
export async function overlaySlot(ctx, site, contributed, entries, slot) {
    for (const { name, path } of entries) {
        const definition = await importDefault(ctx, path, [slot.kind, slot.disabledKind, "disabled"]);
        if (definition === undefined) {
            continue;
        }
        const kind = getDefinitionKind(definition);
        if (kind === slot.disabledKind || kind === "disabled") {
            contributed.delete(name);
            if (!slot.declared.has(name)) {
                unknownContribution(ctx, path, slot.disableHelper, name, site.ns);
            }
            continue;
        }
        const item = await slot.compile(ctx, path, name, definition);
        if (item !== undefined) {
            contributed.set(name, item);
        }
    }
}
export async function overlaySkills(ctx, site, contributed, dir) {
    await overlayNamed(ctx, site, contributed, dir, "disableSkill", (onDisable) => loadSkills(ctx, dir, onDisable));
}
export async function overlayHooks(ctx, site, contributed, dir) {
    await overlayNamed(ctx, site, contributed, dir, "disableHook", (onDisable) => loadHooks(ctx, dir, onDisable));
}
export async function overlaySchedules(ctx, site, contributed, dir) {
    await overlayNamed(ctx, site, contributed, dir, "disableSchedule", (onDisable) => loadSchedules(ctx, dir, onDisable));
}
export async function overlayChannels(ctx, site, contributed, dir) {
    if (!(await isDirectory(dir))) {
        return;
    }
    const declared = new Set(contributed.keys());
    const { channels } = await loadChannels(ctx, dir, "extension", (id, path) => {
        contributed.delete(id);
        if (!declared.has(id)) {
            unknownContribution(ctx, path, "disableChannel", id, site.ns);
        }
    });
    for (const channel of channels) {
        contributed.set(channel.id, channel);
    }
}
export async function overlaySubagents(ctx, site, contributed, dir) {
    if (!(await isDirectory(dir))) {
        return;
    }
    const declared = new Set(contributed.keys());
    for (const child of await loadSubagents(ctx, dir)) {
        contributed.set(child.name, child);
    }
    for (const entry of await sortedEntries(dir)) {
        const path = join(dir, entry.name);
        if (!entry.isFile() || !isModuleFile(entry.name)) {
            continue;
        }
        const name = moduleStem(entry.name);
        const definition = await importDefault(ctx, path, ["disabled"]);
        if (definition === undefined) {
            continue;
        }
        contributed.delete(name);
        if (!declared.has(name)) {
            unknownContribution(ctx, path, "disableSubagent", name, site.ns);
        }
    }
}
export async function overlayInstructionsFragment(ctx, overlayDir) {
    const markdownPath = join(overlayDir, "instructions.md");
    const modulePath = await findModuleFile(overlayDir, "instructions");
    const instructionsDir = join(overlayDir, "instructions");
    if (!(await isFile(markdownPath)) &&
        modulePath === undefined &&
        !(await isDirectory(instructionsDir))) {
        return "keep";
    }
    if (modulePath !== undefined) {
        let mod;
        try {
            mod = await ctx.importModule(modulePath);
        }
        catch (error) {
            pushModuleLoadDiagnostic(ctx, modulePath, error);
            return "keep";
        }
        if (getDefinitionKind(mod.default) === "disabled") {
            return undefined;
        }
    }
    return loadInstructions(ctx, overlayDir, undefined, false);
}
export async function overlayArtifacts(ctx, overlayDir, current) {
    const path = await findModuleFile(overlayDir, "artifacts");
    if (path === undefined) {
        return current;
    }
    const definition = await importDefault(ctx, path, ["artifacts", "disabled"]);
    if (definition === undefined) {
        return current;
    }
    if (getDefinitionKind(definition) === "disabled") {
        return undefined;
    }
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
    return definition;
}
async function overlayNamed(ctx, site, contributed, dir, helper, load) {
    if (!(await isDirectory(dir))) {
        return;
    }
    const declared = new Set(contributed.keys());
    for (const item of await load((name, path) => {
        contributed.delete(name);
        if (!declared.has(name)) {
            unknownContribution(ctx, path, helper, name, site.ns);
        }
    })) {
        contributed.set(item.name, item);
    }
}
function unknownContribution(ctx, path, helper, name, ns) {
    ctx.diagnostics.push({
        severity: "error",
        path: displayPath(ctx, path),
        message: `${helper}() targets "${name}", which extension "${ns}" does not contribute.`,
    });
}
